import "server-only";
import { randomUUID } from "node:crypto";

export type OutgoingEmail = {
  from: string;
  to: string;
  subject: string;
  text: string;
  html?: string;
  /** RFC 5322 Message-ID (with angle brackets) generated by us, so replies can be matched. */
  messageId: string;
  inReplyTo?: string | null;
  references?: string[];
  headers?: Record<string, string>;
  attachments?: { filename: string; contentType: string; content: Uint8Array }[];
};

export type SendResult = { providerMessageId: string; delivered: boolean };

export interface EmailProvider {
  readonly name: "log" | "mailgun";
  send(email: OutgoingEmail): Promise<SendResult>;
}

/** Development provider: logs metadata only, never delivers. */
export class LogEmailProvider implements EmailProvider {
  readonly name = "log" as const;
  async send(email: OutgoingEmail): Promise<SendResult> {
    console.info(
      `[email:log] NOT delivered → to=${email.to} subject="${email.subject}" attachments=${email.attachments?.length ?? 0}`,
    );
    return { providerMessageId: `log-${randomUUID()}`, delivered: false };
  }
}

/** Mailgun HTTP API (EU region by default). Test mode via MAILGUN_TEST_MODE=1 (accepted, not delivered). */
export class MailgunEmailProvider implements EmailProvider {
  readonly name = "mailgun" as const;
  constructor(
    private readonly apiKey: string,
    private readonly domain: string,
    private readonly baseUrl = "https://api.eu.mailgun.net",
    private readonly testMode = false,
  ) {}

  async send(email: OutgoingEmail): Promise<SendResult> {
    const form = new FormData();
    form.set("from", email.from);
    form.set("to", email.to);
    form.set("subject", email.subject);
    form.set("text", email.text);
    if (email.html) form.set("html", email.html);
    form.set("h:Message-Id", email.messageId);
    if (email.inReplyTo) form.set("h:In-Reply-To", email.inReplyTo);
    if (email.references?.length) form.set("h:References", email.references.join(" "));
    for (const [k, v] of Object.entries(email.headers ?? {})) form.set(`h:${k}`, v);
    if (this.testMode) form.set("o:testmode", "yes");
    for (const a of email.attachments ?? []) {
      form.append("attachment", new Blob([Buffer.from(a.content)], { type: a.contentType }), a.filename);
    }
    const res = await fetch(`${this.baseUrl}/v3/${this.domain}/messages`, {
      method: "POST",
      headers: { authorization: `Basic ${Buffer.from(`api:${this.apiKey}`).toString("base64")}` },
      body: form,
      signal: AbortSignal.timeout(30_000),
    });
    const body = (await res.json().catch(() => ({}))) as { id?: string; message?: string };
    if (!res.ok) throw new Error(`Mailgun ${res.status}: ${body.message ?? "chyba odeslání"}`);
    return { providerMessageId: body.id ?? email.messageId, delivered: !this.testMode };
  }
}

/** EMAIL_PROVIDER=mailgun enables real sending; anything else (default) only logs. */
export function getEmailProvider(): EmailProvider {
  if (process.env.EMAIL_PROVIDER === "mailgun") {
    const key = process.env.MAILGUN_API_KEY;
    const domain = process.env.MAILGUN_DOMAIN;
    if (!key || !domain)
      throw new Error("EMAIL_PROVIDER=mailgun, ale chybí MAILGUN_API_KEY nebo MAILGUN_DOMAIN");
    return new MailgunEmailProvider(
      key,
      domain,
      process.env.MAILGUN_BASE_URL || "https://api.eu.mailgun.net",
      process.env.MAILGUN_TEST_MODE === "1",
    );
  }
  return new LogEmailProvider();
}
